<?php namespace App\Filament\Pages;use Filament\Pages\Page;use Illuminate\Support\Facades\DB;
class AttestationSheetWorkspace extends Page{protected static bool $shouldRegisterNavigation=false;protected static string $view='filament.pages.attestation-sheet-workspace';public $sheet;public array $rows=[];
public function mount():void{$id=(int)request('sheet');$p=request()->attributes->get('academic_period');$this->sheet=DB::table('attestation_sheets as a')->join('study_groups as g','g.id','=','a.study_group_id')->join('subjects as s','s.id','=','a.subject_id')->where('a.id',$id)->when($p,fn($q)=>$q->where('a.academic_period_id',$p->id))->select('a.*','g.name as group_name','s.name as subject_name')->first();abort_if(!$this->sheet,404);$this->rows=DB::table('attestation_attempts as x')->join('students as s','s.id','=','x.student_id')->where('x.attestation_sheet_id',$id)->select('x.*','s.last_name','s.first_name','s.middle_name')->orderBy('s.last_name')->orderBy('x.attempt_no')->get()->groupBy('student_id')->map(function($a){$p=$a->firstWhere('attempt_no',0);return['student'=>trim($a->first()->last_name.' '.$a->first()->first_name.' '.$a->first()->middle_name),'primary'=>$p?(array)$p:null,'attempts'=>$a->map(fn($x)=>(array)$x)->all()];})->values()->all();}
public static function canAccess():bool{$u=auth()->user();return $u&&($u->isSuperAdmin()||$u->hasRole('admin')||$u->hasRole('head_academic')||$u->hasRole('academic_head')||$u->canDo('semester.mark'));}}